+  background: rgba(255, 255, 255, 0.9);
+  font-size: 0.86rem;
+  font-weight: 700;
+}
+
+.product-card h3,
+.deal-card h3,
+.editorial-card h3 {
+  margin: 1rem 0 0.5rem;
+  font-size: 1.2rem;
+  letter-spacing: -0.03em;
+}
+
+.product-meta,
+.deal-meta {
+  justify-content: space-between;
+  margin-top: 1rem;
+}
+
+.price {
+  font-size: 1.15rem;
+  font-weight: 800;
+}
+
+.tag {
+  color: var(--success);
+  font-weight: 700;
+}
+
+.deal-card {
+  padding: 1rem;
+  background: linear-gradient(180deg, #ffffff 0%, #f8fafe 100%);
+}
+
+.deal-card:nth-child(2) .deal-visual {
+  background-image: linear-gradient(135deg, rgba(52, 87, 246, 0.82), rgba(124, 58, 237, 0.6));
+}
+
+.deal-card:nth-child(1) .deal-visual {
+  background-image: linear-gradient(135deg, rgba(249, 115, 22, 0.75), rgba(255, 210, 128, 0.8));
+}
+
+.deal-card:nth-child(3) .deal-visual {
+  background-image: linear-gradient(135deg, rgba(20, 32, 51, 0.85), rgba(74, 101, 168, 0.7));
+}
+
+.editorial-grid {
+  align-items: stretch;
+}
+
+.editorial-lead {
+  grid-column: span 5;
+}
+
+.editorial-stack {
+  grid-column: span 7;
+  display: grid;
+  gap: 1.25rem;
+  grid-template-columns: repeat(2, minmax(0, 1fr));
+}
+
+.editorial-card {
+  overflow: hidden;
+}
+
+.editorial-card .card-copy-wrap {
+  padding: 1.1rem 1.1rem 1.25rem;
+}
+
+.footer {
+  padding: 2rem 0 3rem;
+  border-top: 1px solid rgba(211, 219, 231, 0.9);
+}
+
+.footer-title {
+  margin: 0;
+  font-size: 1.4rem;
+  letter-spacing: -0.04em;
+}
+
+.footer-note {
+  max-width: 36rem;
+}
+
+@media (max-width: 1024px) {
+  .hero-copy,
+  .hero-panel,
+  .editorial-lead,
+  .editorial-stack {
+    grid-column: span 12;
+  }
+
+  .product-grid {
+    grid-template-columns: repeat(2, minmax(0, 1fr));
+  }
+
+  .deal-grid,
+  .footer-grid,
+  .editorial-stack {
+    grid-template-columns: 1fr;
+  }
+}
+
+@media (max-width: 720px) {
+  .nav-row,
+  .section-header {
+    align-items: start;
+    flex-direction: column;
+  }
+
+  .product-grid {
+    grid-template-columns: 1fr;
+  }
+
+  .hero h1 {
+    font-size: clamp(2.3rem, 12vw, 3.6rem);
+  }
+}
+
+@media (prefers-reduced-motion: reduce) {
+  html {
+    scroll-behavior: auto;
+  }
+
+  *,
+  *::before,
+  *::after {
+    animation-duration: 0.01ms !important;
+    animation-iteration-count: 1 !important;
+    transition-duration: 0.01ms !important;
+  }
+}
+
+@media (forced-colors: active) {
+  :root {
+    --bg: Canvas;
+    --surface: Canvas;
+    --surface-strong: CanvasText;
+    --text: CanvasText;
+    --muted: CanvasText;
+    --line: ButtonBorder;
+    --brand: Highlight;
+    --brand-strong: Highlight;
+  }
+
+  .button,
+  .card,
+  .hero-copy,
+  .hero-panel,
+  .brand-mark,
+  .skip-link {
+    border: 1px solid ButtonBorder;
+    box-shadow: none;
+  }
+}
+



